INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die ASCII-Tabelle nur für englische Zeichen gedacht?', 2, '[{"text": "Ja", "correct": true, "because": "Ursprünglich für lateinische Zeichen"}, {"text": "Nein", "correct": false, "because": "Erweitert durch ASCII-Varianten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der ASCII-Tabelle?', 3, '[{"text": "Zeichen kodieren", "correct": true, "because": "Nummerische Zuordnung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kodierung, keine Verschlüsselung"}, {"text": "Speicher sparen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur ASCII-Tabelle?', 5, '[{"text": "Buchstaben", "correct": true, "because": "A-Z, a-z enthalten"}, {"text": "Steuerzeichen", "correct": true, "because": "z.B. Enter, Tab"}, {"text": "Emojis", "correct": false, "because": "Nicht in Standard-ASCII"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ASCII verwendet 7 Bit. b) Es enthält kyrillische Zeichen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kyrillisch nicht enthalten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung der ASCII-Tabelle?', 4, '[{"text": "Zeichenkodierung", "correct": false, "because": "Kern der Tabelle"}, {"text": "Nummerische Werte", "correct": false, "because": "Grundlage"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die ASCII-Tabelle 128 Zeichen umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Standard-ASCII mit 7 Bit"}, {"text": "Nein", "correct": false, "because": "128 ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich der ASCII-Tabelle enthält Steuerzeichen?', 3, '[{"text": "0-31", "correct": true, "because": "Nicht druckbare Zeichen"}, {"text": "32-127", "correct": false, "because": "Druckbare Zeichen"}, {"text": "128-255", "correct": false, "because": "Erweiterte ASCII"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur erweiterten ASCII-Tabelle?', 5, '[{"text": "Umlaute", "correct": true, "because": "Mit 8 Bit erweitert"}, {"text": "Sonderzeichen", "correct": true, "because": "z.B. é, ñ"}, {"text": "Unicode", "correct": false, "because": "Separater Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ASCII steht für American Standard Code. b) Es unterstützt alle Sprachen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Begrenzt auf lateinische Zeichen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in der ASCII-Tabelle unwichtig?', 4, '[{"text": "Zeichenzuordnung", "correct": false, "because": "Kernprinzip"}, {"text": "Nummerische Codes", "correct": false, "because": "Grundlage"}, {"text": "Zeichenfarbe", "correct": true, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ASCII 256 Zeichen?', 2, '[{"text": "Nein", "correct": true, "because": "Standard-ASCII hat 128"}, {"text": "Ja", "correct": false, "because": "Erweiterte Version"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die ASCII-Tabelle?', 4, '[{"text": "Einfache Kodierung", "correct": true, "because": "Standardisiert Zeichen"}, {"text": "Kompatibilität", "correct": true, "because": "Weit verbreitet"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ASCII veraltet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Basis für moderne Systeme"}, {"text": "Ja", "correct": false, "because": "Immer noch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung der ASCII-Tabelle?', 3, '[{"text": "Zeichenkodierung", "correct": true, "because": "Hauptfunktion"}, {"text": "Speichereffizienz", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ASCII enthält Steuerzeichen. b) Es unterstützt Unicode direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unicode ist eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die ASCII-Tabelle?', 5, '[{"text": "Begrenzte Zeichen", "correct": true, "because": "Nur 128 im Standard"}, {"text": "Keine multilingualen Zeichen", "correct": true, "because": "Lateinisch beschränkt"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in der ASCII-Tabelle unwichtig?', 3, '[{"text": "Kodierte Zeichen", "correct": false, "because": "Kernbestandteil"}, {"text": "Nummerische Werte", "correct": false, "because": "Grundlage"}, {"text": "Fontgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt ASCII Sonderzeichen wie Umlaute?', 3, '[{"text": "Nein", "correct": true, "because": "Nur in erweiterter Version"}, {"text": "Ja", "correct": false, "because": "Standard-ASCII begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ASCII 8 Bit umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Erweiterte ASCII-Version"}, {"text": "Nein", "correct": false, "because": "7 Bit Standard, 8 Bit erweitert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Code gehört zur ASCII-Tabelle?', 4, '[{"text": "65 für A", "correct": true, "because": "Korrekte Zuordnung"}, {"text": "256 für Z", "correct": false, "because": "Außerhalb Standard"}, {"text": "1000 für a", "correct": false, "because": "Zu hoch"}]');
